 jsonb_build_object('heading','Modele a análise crítica','content',jsonb_build_array('Ensine a verificar título, fonte, data, escala, legenda, unidade de medida e recorte territorial antes de interpretar.','Compare dados e mapas, identifique padrões, conecte causas e consequências e diferencie evidência, inferência e opinião.','Em propostas ambientais, considere impacto, viabilidade, responsabilidade pública e coletiva, acessibilidade e possíveis efeitos não previstos.')),
 jsonb_build_object('heading','Rotina adaptativa','content',jsonb_build_array('Antecipe conceitos, divida gráficos e mapas em camadas, dê uma instrução por vez e ofereça pistas graduadas.','Aceite fala, apontamento, cartões, mapa, tabela, gráfico, esquema, desenho, áudio, digitação, escrita ou tecnologia assistiva.','Não use rapidez, memória, leitura, visão, fala, cálculo ou coordenação motora como medida isolada da compreensão geográfica.')),
 jsonb_build_object('heading','Critério','content','Resolve quatro de cinco situações e sustenta ao menos três conclusões com dado, elemento cartográfico ou relação territorial pertinente.')))),
jsonb_build_array(jsonb_build_object('title','1. Verificar a fonte','instruction','Localize título, fonte, data, legenda, escala, unidade e recorte quando disponíveis.','activity','Registre duas informações verificáveis e uma limitação do material.','support','Leitura mediada, ampliação, tabela simplificada e descrição verbal ou tátil.'),jsonb_build_object('title','2. Identificar padrões e relações','instruction','Compare dados, mapas, paisagens, redes ou fluxos de cenários fictícios.','activity','Monte quadro, gráfico acessível, mapa ou cadeia causa-consequência sobre '||lower(title)||'.','support','Exemplo resolvido, prática guiada e pistas graduadas.'),jsonb_build_object('title','3. Avaliar e argumentar','instruction','Apresente uma conclusão, cite a evidência e considere outra explicação possível.','activity','Compare propostas por impacto, viabilidade, equidade e responsabilidade coletiva.','support','Resposta oral, apontada, esquemática, gravada, digitada, escrita ou assistida.')),
jsonb_build_array(jsonb_build_object('page',1,'answer','Identifica elementos da fonte, duas informações e uma limitação.'),jsonb_build_object('page',2,'answer','Reconhece padrão ou relação sem extrapolar os dados.'),jsonb_build_object('page',3,'answer','Argumento sustentado por evidência e avaliação equilibrada da proposta.','teacher_note','Registre raciocínio, autonomia, apoio eficaz e próximo passo; não registre localização, renda, consumo ou trajetória familiar real.')),
